static Display_GfxResult_t Display_TextDrawBitmap(uint16_t x, uint16_t y, const Display_TextBitmap_t *bitmap, uint16_t color)
{
  uint16_t row;
  uint16_t col;

  if ((bitmap == 0) || (Display_GfxIsReady() == 0U)) { return DISPLAY_GFX_PARAM_ERROR; }

  /* 按行扫描，把同一行连续的亮点合并成一次已窗口化的 FillRect。
     着色像素集合与逐点绘制完全一致，可工作在任意背景之上。 */
  for (row = 0U; row < bitmap->height; row++) {
    col = 0U;
    while (col < bitmap->width) {
      uint16_t byte_index = (uint16_t)((row * bitmap->bytes_per_row) + (col / 8U));
      uint8_t mask        = (uint8_t)(0x80U >> (col & 0x07U));
      if ((bitmap->data[byte_index] & mask) != 0U) {
        uint16_t run_start = col;
        do {
          col++;
        } while ((col < bitmap->width) && ((bitmap->data[(row * bitmap->bytes_per_row) + (col / 8U)] & (uint8_t)(0x80U >> (col & 0x07U))) != 0U));
        (void)Display_GfxFillRect((uint16_t)(x + run_start), (uint16_t)(y + row), (uint16_t)(col - run_start), 1U, color);
      } else {
        col++;
      }
    }
  }

  return DISPLAY_GFX_OK;
}

/* 绘制任意尺寸的 1bpp 位图（逐行 MSB 优先），供告警页中文字模等外部数据使用。 */
Display_GfxResult_t Display_TextDrawRawBitmap(uint16_t x, uint16_t y, uint16_t width, uint16_t height, uint16_t bytes_per_row, const uint8_t *data, uint16_t color)
{
  Display_TextBitmap_t bitmap;

  bitmap.width         = width;
  bitmap.height        = height;
  bitmap.bytes_per_row = bytes_per_row;
  bitmap.data          = data;
  return Display_TextDrawBitmap(x, y, &bitmap, color);
}

static Display_GfxResult_t Display_TextDrawBitmapBold(uint16_t x, uint16_t y, const Display_TextBitmap_t *bitmap, uint16_t color)
{
  uint16_t row;
  uint16_t col;

  if ((bitmap == 0) || (Display_GfxIsReady() == 0U)) { return DISPLAY_GFX_PARAM_ERROR; }

  /* 加粗 = 每个亮点画 2x2 块。一行连续亮点 [c0..c1] 的并集等于
     列 [c0, c1+1] x 行 [row, row+1]，合并成一次 FillRect(run+1, 2)。 */
  for (row = 0U; row < bitmap->height; row++) {
    col = 0U;
    while (col < bitmap->width) {
      uint16_t byte_index = (uint16_t)((row * bitmap->bytes_per_row) + (col / 8U));
      uint8_t mask        = (uint8_t)(0x80U >> (col & 0x07U));
      if ((bitmap->data[byte_index] & mask) != 0U) {
        uint16_t run_start = col;
        do {
          col++;
        } while ((col < bitmap->width) && ((bitmap->data[(row * bitmap->bytes_per_row) + (col / 8U)] & (uint8_t)(0x80U >> (col & 0x07U))) != 0U));
        (void)Display_GfxFillRect((uint16_t)(x + run_start), (uint16_t)(y + row), (uint16_t)(col - run_start + 1U), 2U, color);
      } else {
        col++;
      }
    }
  }

  return DISPLAY_GFX_OK;
}

