/* Draw a single ASCII digit (scale 2) aligned with the 16px glyph row. */
static uint16_t Display_TextDrawDigit(uint16_t x, uint16_t y, char d, uint16_t color)
{
  char s[2];

  s[0] = d;
  s[1] = '\0';
  (void)Display_GfxDrawString(x, (uint16_t)(y + 1U), s, color, 2U);
  return 12U;
}

/* Draw a numbered-motor fault: "<n> hao dian ji gu zhang". */
static uint16_t Display_TextDrawMotorFault(uint16_t x, uint16_t y, char index, uint16_t color)
{
  uint16_t cx = x;

  cx = (uint16_t)(cx + Display_TextDrawDigit(cx, y, index, color));
  cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_HAO, color));
  cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DIAN, color));
  cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_JI, color));
  cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_GU, color));
  cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_ZHANG, color));
  return (uint16_t)(cx - x);
}

Display_GfxResult_t Display_TextDrawLogMessage(uint16_t x, uint16_t y, Display_LogMsg_t msg, uint16_t color)
{
  uint16_t cx = x;

  switch (msg) {
    case DISPLAY_LOGMSG_SYSTEM_START:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_XI, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_TONG_SYS, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_QI, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_DONG, color);
      break;

    case DISPLAY_LOGMSG_SELFCHECK_OK:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_ZI_SELF, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_JIAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_TONG, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_GUO, color);
      break;

    case DISPLAY_LOGMSG_SELFCHECK_PART:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_ZI_SELF, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_JIAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_BU, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_FEN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_TONG, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_GUO, color);
      break;

    case DISPLAY_LOGMSG_SELFCHECK_FAIL:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_ZI_SELF, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_JIAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_WEI, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_TONG, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_GUO, color);
      break;

    case DISPLAY_LOGMSG_GPS_OK:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_G, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_P, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_S, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_ZHENG, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_CHANG, color);
      break;

    case DISPLAY_LOGMSG_GPS_NOSIG:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_G, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_P, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_S, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_WU, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_XIN, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_HAO, color);
      break;

    case DISPLAY_LOGMSG_GPS_LOST:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_G, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_P, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_S, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DUAN, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_KAI, color);
      break;

    case DISPLAY_LOGMSG_ATT_OK:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_ZI_POSE, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_TAI, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_ZHENG, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_CHANG, color);
      break;

    case DISPLAY_LOGMSG_ATT_LOST:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_ZI_POSE, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_TAI, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DUAN, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_KAI, color);
      break;

    case DISPLAY_LOGMSG_ENV_OK:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_HUAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_JING_ENV, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_ZHENG, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_CHANG, color);
      break;

    case DISPLAY_LOGMSG_ENV_LOST:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_HUAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_JING_ENV, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DUAN, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_KAI, color);
      break;

    case DISPLAY_LOGMSG_COMM_OK:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_TONG, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_XIN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_ZHENG, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_CHANG, color);
      break;

    case DISPLAY_LOGMSG_COMM_LOST:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_TONG, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_XIN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DUAN, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_KAI, color);
      break;

    case DISPLAY_LOGMSG_STORAGE_OK:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_CUN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_CHU, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_ZHENG, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_CHANG, color);
      break;

    case DISPLAY_LOGMSG_STORAGE_LOST:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_CUN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_CHU, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DUAN, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_KAI, color);
      break;

    case DISPLAY_LOGMSG_MOTOR_OK:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DIAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_JI, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_ZHENG, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_CHANG, color);
      break;

    case DISPLAY_LOGMSG_MOTOR_DISCONNECT:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DIAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_JI, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DUAN, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_KAI, color);
      break;

    case DISPLAY_LOGMSG_MOTOR_LOWPOWER:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DIAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_JI, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_GONG, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DIAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_BU_NOT, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_ZU, color);
      break;

    case DISPLAY_LOGMSG_MOTOR1_FAIL:
      (void)Display_TextDrawMotorFault(x, y, '1', color);
      break;
    case DISPLAY_LOGMSG_MOTOR2_FAIL:
      (void)Display_TextDrawMotorFault(x, y, '2', color);
      break;
    case DISPLAY_LOGMSG_MOTOR3_FAIL:
      (void)Display_TextDrawMotorFault(x, y, '3', color);
      break;
    case DISPLAY_LOGMSG_MOTOR4_FAIL:
      (void)Display_TextDrawMotorFault(x, y, '4', color);
      break;

    case DISPLAY_LOGMSG_MOTOR_ALL_FAIL:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_QUAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_BU, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DIAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_JI, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_GU, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_ZHANG, color);
      break;

    case DISPLAY_LOGMSG_MOTOR_DEAD: /* 电机电池没电 */
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DIAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_JI, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DIAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_CHI, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_MEI, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_DIAN, color);
      break;

    case DISPLAY_LOGMSG_MOTOR_CHARGE: /* 电机电池需充电 */
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DIAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_JI, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DIAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_CHI, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_XU, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_CHONG, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_DIAN, color);
      break;

    case DISPLAY_LOGMSG_MAIN_CHARGE: /* 主控电池需充电 */
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_ZHU, color));
      (void)Display_TextDrawBitmap(cx, y, &s_mlg_kong_aircraft_bitmap, color); /* 控：用与“主控”标签一致的字模 */
      cx = (uint16_t)(cx + s_mlg_kong_aircraft_bitmap.width);
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_DIAN, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_CHI, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_XU, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_CHONG, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_DIAN, color);
      break;

    case DISPLAY_LOGMSG_ALARM_ACTIVE:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_YOU, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_GAO, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_JING_WARN, color);
      break;

    case DISPLAY_LOGMSG_ALARM_NONE:
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_WU, color));
      cx = (uint16_t)(cx + Display_TextDrawGlyph(cx, y, MLG_GAO, color));
      (void)Display_TextDrawGlyph(cx, y, MLG_JING_WARN, color);
      break;

    default:
      return DISPLAY_GFX_PARAM_ERROR;
  }

  return DISPLAY_GFX_OK;
}
